import { Actor } from './entities/Actor';

export interface TimelineEntry {
  readonly actor: Actor;
  readonly scheduledTime: number;
  readonly relativeDelay: number;
}

/**
 * Priority-queue turn scheduler that tracks actor action timestamps on the dungeon timeline.
 * Supports variable actor speeds (derived from AGI), triggers tick-based HP/MP regeneration
 * as dungeon time advances, and provides upcoming turn previews for the Timeline UI.
 */
export class TimelineScheduler {
  private readonly actors: Actor[] = [];
  private _currentTime = 0;
  private _turnCount = 0;

  public get currentTime(): number {
    return this._currentTime;
  }

  public get turnCount(): number {
    return this._turnCount;
  }

  public restoreState(currentTime: number, turnCount: number): void {
    this._currentTime = Math.max(0, currentTime);
    this._turnCount = Math.max(0, turnCount);
    this.sortQueue();
  }

  public addActor(actor: Actor, initialTime = this._currentTime): void {
    if (this.actors.some((a) => a.id === actor.id)) {
      return;
    }
    actor.nextActionTime = initialTime;
    this.actors.push(actor);
    this.sortQueue();
  }

  public removeActor(actorId: string): void {
    const idx = this.actors.findIndex((a) => a.id === actorId);
    if (idx !== -1) {
      this.actors.splice(idx, 1);
    }
  }

  public peekNextActor(): Actor | null {
    this.pruneDeadActors();
    this.sortQueue();
    return this.actors[0] ?? null;
  }

  /**
   * Advances the given actor by baseTimeCost (scaled by actor.speed) and updates currentTime,
   * triggering tick-based HP/MP regeneration across all living actors for any elapsed dungeon ticks.
   */
  public recordAction(actor: Actor, baseTimeCost: number): void {
    const previousTime = this._currentTime;
    actor.advanceTime(baseTimeCost);
    this._turnCount++;
    this.pruneDeadActors();
    this.sortQueue();
    if (this.actors.length > 0) {
      this._currentTime = this.actors[0].nextActionTime;
      const elapsedTicks = this._currentTime - previousTime;
      if (elapsedTicks > 0) {
        for (const a of this.actors) {
          a.regenerateOverTicks(elapsedTicks);
        }
      }
    }
  }

  /**
   * Returns a preview of the upcoming turn order (across multiple future cycles if needed)
   * for rendering the Timeline UI bar.
   */
  public getUpcomingEntries(count = 6): TimelineEntry[] {
    this.pruneDeadActors();
    if (this.actors.length === 0 || count <= 0) {
      return [];
    }

    const simulated = this.actors.map((actor) => ({
      actor,
      time: actor.nextActionTime,
      stepCost: Math.max(1, Math.round((100 * 100) / Math.max(1, actor.speed))),
    }));

    const entries: TimelineEntry[] = [];
    for (let i = 0; i < count; i++) {
      simulated.sort((a, b) => {
        if (a.time !== b.time) return a.time - b.time;
        if (a.actor.isPlayer !== b.actor.isPlayer) return a.actor.isPlayer ? -1 : 1;
        return a.actor.id.localeCompare(b.actor.id);
      });
      const next = simulated[0];
      entries.push({
        actor: next.actor,
        scheduledTime: next.time,
        relativeDelay: Math.max(0, next.time - this._currentTime),
      });
      next.time += next.stepCost;
    }

    return entries;
  }

  public clear(): void {
    this.actors.length = 0;
    this._currentTime = 0;
    this._turnCount = 0;
  }

  private pruneDeadActors(): void {
    for (let i = this.actors.length - 1; i >= 0; i--) {
      if (!this.actors[i].isAlive()) {
        this.actors.splice(i, 1);
      }
    }
  }

  private sortQueue(): void {
    this.actors.sort((a, b) => {
      if (a.nextActionTime !== b.nextActionTime) {
        return a.nextActionTime - b.nextActionTime;
      }
      // Player breaks ties first
      if (a.isPlayer !== b.isPlayer) {
        return a.isPlayer ? -1 : 1;
      }
      return a.id.localeCompare(b.id);
    });
  }
}
