import { Point } from '../types';
import { Actor, ActorStats, PrimaryAttributes } from './Actor';

/**
 * The human player character controlled by the user.
 */
export class Player extends Actor {
  constructor(
    position: Point,
    customStats?: Partial<ActorStats>,
    customAttributes?: Partial<PrimaryAttributes>,
    name = 'Howard'
  ) {
    super({
      id: 'player',
      name,
      position,
      spriteKey: 'player_human',
      isPlayer: true,
      attributes: customAttributes,
      stats: customStats,
    });
  }
}
