import type { Enemy } from '../enemies/Enemy';
import { Actor, ATTRIBUTE_EXERCISE_GAINS } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { isAdjacent } from '../types';
import { Action, ActionResult, DEFAULT_ACTION_TIME_COST, MELEE_SP_COST } from './Action';

/**
 * Resolves a melee physical attack from `attacker` against an adjacent `target` actor:
 * - Hit roll: clamp(85 + (attacker.accuracy - target.evasion), 15, 98)
 * - Crit roll: clamp(attacker.critChance - target.critAvoidance, 0, 75) -> 1.5x damage
 * - Damage: max(1, floor(attacker.physicalAttack - target.physicalDefense * 0.5))
 * - Removes defeated enemies from the world and timeline.
 */
export class MeleeAttackAction implements Action {
  public readonly type = 'melee_attack';
  public readonly target: Actor;

  constructor(target: Actor) {
    this.target = target;
  }

  public execute(attacker: Actor, world: GameWorld): ActionResult {
    if (!attacker.isAlive() || !this.target.isAlive()) {
      return { success: false, timeCost: 0, message: 'Target is no longer alive.' };
    }

    if (!isAdjacent(attacker.position, this.target.position)) {
      return { success: false, timeCost: 0, message: 'Target is out of melee range.' };
    }

    if (!attacker.consumeSp(MELEE_SP_COST, false)) {
      const noSpMsg = 'Not enough stamina (SP)!';
      if (attacker.isPlayer) {
        world.eventBus.log(noSpMsg, 'combat', world.timeline.currentTime, 'notEnoughStamina', {
          actor: attacker.logName,
          required: MELEE_SP_COST,
        });
      }
      return { success: false, timeCost: 0, message: noSpMsg };
    }

    const hitChance = Math.min(
      98,
      Math.max(15, 85 + (attacker.stats.accuracy - this.target.stats.evasion))
    );
    const hitRoll = world.nextRandom() * 100;

    if (hitRoll >= hitChance) {
      const missMsg = attacker.isPlayer
        ? `You attack ${this.target.name}, but miss.`
        : this.target.isPlayer
          ? `${attacker.name} attacks you, but misses.`
          : `${attacker.name} attacks ${this.target.name}, but misses.`;
      world.eventBus.log(missMsg, 'combat', world.timeline.currentTime, 'attackMissed', {
        attacker: attacker.logName,
        defender: this.target.logName,
      });
      attacker.exerciseAttribute('str', ATTRIBUTE_EXERCISE_GAINS.meleeMissStrXp);
      attacker.exerciseAttribute('agi', MELEE_SP_COST * ATTRIBUTE_EXERCISE_GAINS.agiXpPerSpSpent);
      return {
        success: true,
        timeCost: DEFAULT_ACTION_TIME_COST,
        message: missMsg,
      };
    }

    const critChance = Math.min(
      75,
      Math.max(0, attacker.stats.critChance - this.target.stats.critAvoidance)
    );
    const isCrit = world.nextRandom() * 100 < critChance;

    const baseDamage = Math.max(
      1,
      Math.floor(attacker.stats.physicalAttack - this.target.stats.physicalDefense * 0.5)
    );
    const finalDamage = isCrit
      ? Math.max(1, Math.round(baseDamage * attacker.stats.critMultiplier))
      : baseDamage;

    const actualDamage = Math.min(this.target.stats.hp, finalDamage);
    this.target.stats.hp = Math.max(0, this.target.stats.hp - finalDamage);

    if (attacker.isPlayer) {
      world.recordDamageDealt(actualDamage);
    }
    if (this.target.isPlayer) {
      world.recordDamageTaken(actualDamage, attacker);
    }

    const hitMsg = isCrit
      ? attacker.isPlayer
        ? `Critical hit! You strike ${this.target.name} for ${finalDamage} damage!`
        : this.target.isPlayer
          ? `Critical hit! ${attacker.name} strikes you for ${finalDamage} damage!`
          : `Critical hit! ${attacker.name} strikes ${this.target.name} for ${finalDamage} damage!`
      : attacker.isPlayer
        ? `You attack ${this.target.name} for ${finalDamage} damage.`
        : this.target.isPlayer
          ? `${attacker.name} attacks you for ${finalDamage} damage.`
          : `${attacker.name} attacks ${this.target.name} for ${finalDamage} damage.`;

    world.eventBus.log(
      hitMsg,
      'combat',
      world.timeline.currentTime,
      isCrit ? 'attackCrit' : 'attackHit',
      {
        attacker: attacker.logName,
        defender: this.target.logName,
        damage: finalDamage,
      }
    );

    if (!this.target.isAlive()) {
      const defeatMsg = this.target.isPlayer
        ? 'You are defeated!'
        : `${this.target.name} is defeated!`;
      world.eventBus.log(
        defeatMsg,
        'combat',
        world.timeline.currentTime,
        'actorDefeated',
        {
          defender: this.target.logName,
        }
      );
      if (!this.target.isPlayer) {
        world.recordEnemyDefeated(this.target as Enemy);
        world.removeEnemy(this.target.id);
      }
    } else if (actualDamage > 0) {
      this.target.exerciseAttribute('con', actualDamage * ATTRIBUTE_EXERCISE_GAINS.conXpPerHpLost);
    }

    attacker.exerciseAttribute('str', ATTRIBUTE_EXERCISE_GAINS.meleeHitStrXp);
    attacker.exerciseAttribute('agi', MELEE_SP_COST * ATTRIBUTE_EXERCISE_GAINS.agiXpPerSpSpent);

    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
      message: hitMsg,
    };
  }
}
