import { Item } from './Item';

/**
 * Container for items held by an Actor (Player or NPC/Enemy).
 * Automatically merges stackable items and computes total carry weight.
 */
export class Inventory {
  private readonly items: Item[] = [];
  private readonly onChange?: (totalWeight: number) => void;

  constructor(onChange?: (totalWeight: number) => void) {
    this.onChange = onChange;
  }

  public getItems(): readonly Item[] {
    return this.items;
  }

  public get count(): number {
    return this.items.length;
  }

  public isEmpty(): boolean {
    return this.items.length === 0;
  }

  public getTotalWeight(): number {
    return Number(
      this.items.reduce((sum, item) => sum + item.totalWeight, 0).toFixed(2)
    );
  }

  public addItem(incoming: Item): Item {
    if (incoming.stackable) {
      const existing = this.items.find((i) => i.canStackWith(incoming));
      if (existing) {
        existing.amount += incoming.amount;
        this.notifyChange();
        return existing;
      }
    }

    const copy = incoming.cloneWithAmount(incoming.amount, incoming.id);
    this.items.push(copy);
    this.notifyChange();
    return copy;
  }

  public removeItemAt(index: number, amountToRemove = 1): Item | null {
    if (index < 0 || index >= this.items.length || amountToRemove <= 0) {
      return null;
    }

    const target = this.items[index];
    const actualAmount = Math.min(target.amount, Math.floor(amountToRemove));
    if (actualAmount <= 0) {
      return null;
    }

    if (actualAmount >= target.amount) {
      const [removed] = this.items.splice(index, 1);
      this.notifyChange();
      return removed;
    }

    target.amount -= actualAmount;
    const split = target.cloneWithAmount(actualAmount);
    this.notifyChange();
    return split;
  }

  public clear(): void {
    this.items.length = 0;
    this.notifyChange();
  }

  private notifyChange(): void {
    this.onChange?.(this.getTotalWeight());
  }
}
