import { ConcreteItemOptions, Item } from './Item';

export interface ManaPotionOptions extends ConcreteItemOptions {
  readonly manaAmount?: number;
}

/**
 * Consumable potion that restores MP when consumed.
 */
export class ManaPotion extends Item {
  public readonly manaAmount: number;

  constructor(options: ManaPotionOptions) {
    super({
      id: options.id ?? `mana-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Mana Potion',
      itemTypeId: 'mana_potion',
      itemType: 'consumable',
      position: options.position,
      spriteKey: 'item_potion',
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      description:
        options.description ??
        'A shimmering azure elixir that restores 20 MP when consumed.',
    });
    this.manaAmount = options.manaAmount ?? 20;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): ManaPotion {
    return new ManaPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      manaAmount: this.manaAmount,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { manaAmount: this.manaAmount };
  }
}
