import { deserializeItem, Inventory, SerializedItem } from '../items';
import { DEFAULT_SIGHT_RADIUS, Point } from '../types';
import { Entity } from './Entity';

/**
 * The 6 Primary Character Attributes shared by Player and NPCs/Enemies:
 * - STR (Strength): Max carry weight & physical attack power.
 * - CON (Constitution): Max HP, HP regeneration speed, & physical defense.
 * - INT (Intelligence): Magic attack power & minor magic defense.
 * - WIS (Wisdom): Max MP, MP regeneration speed, & magic defense.
 * - AGI (Agility): Physical accuracy, evasion, & action/movement frequency (speed).
 * - LUK (Luck): Critical hit chance, critical avoidance, & minor evasion/loot luck.
 */
export interface PrimaryAttributes {
  str: number;
  con: number;
  int: number;
  wis: number;
  agi: number;
  luk: number;
}

export const DEFAULT_PRIMARY_ATTRIBUTES: Readonly<PrimaryAttributes> = {
  str: 10,
  con: 10,
  int: 10,
  wis: 10,
  agi: 10,
  luk: 10,
};

export const PLAYER_LOG_TOKEN = '@player';

export type PrimaryAttributeKey = keyof PrimaryAttributes;

export interface AttributeGrowthConfig {
  readonly base: number;
  readonly slope: number;
}

export const DEFAULT_ATTRIBUTE_GROWTH_CONFIG: Readonly<AttributeGrowthConfig> = {
  base: 10,
  slope: 6,
};

export const ATTRIBUTE_EXERCISE_GAINS = {
  meleeHitStrXp: 12,
  meleeMissStrXp: 4,
  conXpPerHpLost: 1.5,
  magicCastIntXp: 15,
  wisXpPerMpSpent: 1.5,
  agiXpPerSpSpent: 0.6,
} as const;

export interface AttributeLevelUpEvent {
  readonly attribute: PrimaryAttributeKey;
  readonly oldValue: number;
  readonly newValue: number;
}

/**
 * Parameterized linear XP requirement for increasing `currentBaseLevel` to `currentBaseLevel + 1`:
 * xpRequired(L) = max(1, round(base + slope * L))
 */
export function computeAttributeXpRequired(
  currentBaseLevel: number,
  config: AttributeGrowthConfig = DEFAULT_ATTRIBUTE_GROWTH_CONFIG
): number {
  return Math.max(1, Math.round(config.base + config.slope * currentBaseLevel));
}

export type SpRegenMultiplier = 0 | 0.5 | 1;

export interface DerivedStats {
  maxHp: number;
  hpRegenPer100Ticks: number;
  maxMp: number;
  mpRegenPer100Ticks: number;
  maxSp: number;
  spRegenPer100Ticks: number;
  maxCarryWeight: number;
  physicalAttack: number;
  physicalDefense: number;
  magicAttack: number;
  magicDefense: number;
  accuracy: number;
  evasion: number;
  speed: number;
  critChance: number;
  critAvoidance: number;
  critMultiplier: number;
  isBurdened: boolean;
}

export interface ActorStats extends DerivedStats {
  hp: number;
  mp: number;
  sp: number;
  attack: number;
  defense: number;
  sightRadius: number;
}

export interface SerializedActorState {
  readonly id: string;
  readonly name: string;
  readonly spriteKey: string;
  readonly position: Point;
  readonly baseAttributes: PrimaryAttributes;
  readonly attributeBonuses: Partial<PrimaryAttributes>;
  readonly attributeXp: Record<PrimaryAttributeKey, number>;
  readonly growthConfig: AttributeGrowthConfig;
  readonly enableAttributeGrowth: boolean;
  readonly hp: number;
  readonly mp: number;
  readonly sp: number;
  readonly sightRadius: number;
  readonly nextActionTime: number;
  readonly lastActionSpRegenMultiplier: SpRegenMultiplier;
  readonly hpRegenAccumulator: number;
  readonly mpRegenAccumulator: number;
  readonly spRegenAccumulator: number;
  readonly customStatOverrides?: Partial<ActorStats>;
  readonly inventory: readonly SerializedItem[];
}

export interface ActorProps {
  readonly id: string;
  readonly name: string;
  readonly position: Point;
  readonly spriteKey: string;
  readonly isPlayer?: boolean;
  readonly enableAttributeGrowth?: boolean;
  readonly growthConfig?: Partial<AttributeGrowthConfig>;
  readonly attributes?: Partial<PrimaryAttributes>;
  readonly stats?: Partial<ActorStats>;
  readonly currentCarryWeight?: number;
}

/**
 * Pure calculator that computes DerivedStats from PrimaryAttributes, bonuses, and carry weight.
 */
export function computeDerivedStats(
  base: PrimaryAttributes,
  bonuses: Partial<PrimaryAttributes> = {},
  currentCarryWeight = 0
): DerivedStats {
  const str = Math.max(1, base.str + (bonuses.str ?? 0));
  const con = Math.max(1, base.con + (bonuses.con ?? 0));
  const int = Math.max(1, base.int + (bonuses.int ?? 0));
  const wis = Math.max(1, base.wis + (bonuses.wis ?? 0));
  const agi = Math.max(1, base.agi + (bonuses.agi ?? 0));
  const luk = Math.max(1, base.luk + (bonuses.luk ?? 0));

  const maxHp = Math.round(40 + con * 6);
  const hpRegenPer100Ticks = Number((0.2 + con * 0.08).toFixed(3));
  const maxMp = Math.round(10 + wis * 4);
  const mpRegenPer100Ticks = Number((0.5 + wis * 0.15).toFixed(3));
  const maxSp = Math.round(100 + con * 3);
  const spRegenPer100Ticks = Number((5.0 + con * 0.3).toFixed(3));
  const maxCarryWeight = Number((20 + str * 5).toFixed(1));

  const physicalAttack = Math.round(5 + str * 1.5);
  const physicalDefense = Math.floor(con * 0.5);
  const magicAttack = Math.round(5 + int * 1.5);
  const magicDefense = Math.floor(wis * 0.5 + int * 0.2);

  const isBurdened = currentCarryWeight > maxCarryWeight;
  const encumbranceFactor = isBurdened ? 0.75 : 1.0;

  const accuracy = Math.round(80 + agi * 2);
  const rawEvasion = agi * 2 + Math.floor(luk * 0.5);
  const evasion = Math.max(0, Math.round(rawEvasion * encumbranceFactor));

  const rawSpeed = 80 + agi * 2;
  const speed = Math.max(10, Math.round(rawSpeed * encumbranceFactor));

  const critChance = Number(Math.min(75, Math.max(0, 2 + luk * 0.8)).toFixed(2));
  const critAvoidance = Number((luk * 0.3).toFixed(2));
  const critMultiplier = 1.5;

  return {
    maxHp,
    hpRegenPer100Ticks,
    maxMp,
    mpRegenPer100Ticks,
    maxSp,
    spRegenPer100Ticks,
    maxCarryWeight,
    physicalAttack,
    physicalDefense,
    magicAttack,
    magicDefense,
    accuracy,
    evasion,
    speed,
    critChance,
    critAvoidance,
    critMultiplier,
    isBurdened,
  };
}

/**
 * Base class for active creatures (Player and NPCs/Enemies) that participate in the Timeline
 * and have PrimaryAttributes (STR, CON, INT, WIS, AGI, LUK), DerivedStats, FOV sight radius,
 * and timeline-tick-based HP/MP regeneration.
 */
export class Actor extends Entity {
  public readonly isPlayer: boolean;
  public readonly inventory: Inventory;
  public baseAttributes: PrimaryAttributes;
  public attributeBonuses: Partial<PrimaryAttributes>;
  public stats: ActorStats;
  public nextActionTime: number;
  public lastActionSpRegenMultiplier: SpRegenMultiplier = 1;
  public enableAttributeGrowth: boolean;
  public growthConfig: AttributeGrowthConfig;
  public readonly attributeXp: Record<PrimaryAttributeKey, number>;
  private onAttributeLevelUp?: (event: AttributeLevelUpEvent) => void;
  private _currentCarryWeight: number;
  private readonly customStatOverrides: Partial<ActorStats>;
  private hpRegenAccumulator = 0;
  private mpRegenAccumulator = 0;
  private spRegenAccumulator = 0;

  constructor(props: ActorProps) {
    super({
      id: props.id,
      name: props.name,
      position: props.position,
      spriteKey: props.spriteKey,
      blocksMovement: true,
    });
    this.isPlayer = props.isPlayer ?? false;
    this.enableAttributeGrowth = props.enableAttributeGrowth ?? this.isPlayer;
    this.growthConfig = {
      ...DEFAULT_ATTRIBUTE_GROWTH_CONFIG,
      ...props.growthConfig,
    };
    this.attributeXp = {
      str: 0,
      con: 0,
      int: 0,
      wis: 0,
      agi: 0,
      luk: 0,
    };
    this.baseAttributes = {
      ...DEFAULT_PRIMARY_ATTRIBUTES,
      ...props.attributes,
    };
    this.attributeBonuses = {};
    this._currentCarryWeight = Math.max(0, props.currentCarryWeight ?? 0);
    this.customStatOverrides = props.stats ? { ...props.stats } : {};

    const derived = computeDerivedStats(
      this.baseAttributes,
      this.attributeBonuses,
      this._currentCarryWeight
    );

    const maxHp = this.customStatOverrides.maxHp ?? derived.maxHp;
    const maxMp = this.customStatOverrides.maxMp ?? derived.maxMp;
    const maxSp = this.customStatOverrides.maxSp ?? derived.maxSp;
    const physicalAttack =
      this.customStatOverrides.physicalAttack ??
      this.customStatOverrides.attack ??
      derived.physicalAttack;
    const physicalDefense =
      this.customStatOverrides.physicalDefense ??
      this.customStatOverrides.defense ??
      derived.physicalDefense;

    this.stats = {
      ...derived,
      ...this.customStatOverrides,
      maxHp,
      hp: this.customStatOverrides.hp ?? maxHp,
      maxMp,
      mp: this.customStatOverrides.mp ?? maxMp,
      maxSp,
      sp: this.customStatOverrides.sp ?? maxSp,
      physicalAttack,
      attack: physicalAttack,
      physicalDefense,
      defense: physicalDefense,
      sightRadius: this.customStatOverrides.sightRadius ?? DEFAULT_SIGHT_RADIUS,
    };

    this.inventory = new Inventory((totalWeight) => {
      this.currentCarryWeight = totalWeight;
    });

    this.nextActionTime = 0;
  }

  public get attributes(): PrimaryAttributes {
    return {
      str: this.baseAttributes.str + (this.attributeBonuses.str ?? 0),
      con: this.baseAttributes.con + (this.attributeBonuses.con ?? 0),
      int: this.baseAttributes.int + (this.attributeBonuses.int ?? 0),
      wis: this.baseAttributes.wis + (this.attributeBonuses.wis ?? 0),
      agi: this.baseAttributes.agi + (this.attributeBonuses.agi ?? 0),
      luk: this.baseAttributes.luk + (this.attributeBonuses.luk ?? 0),
    };
  }

  /**
   * Returns `@player` when `isPlayer` is true so all log messages format the player as "You"/"you" ("你"),
   * or the actor's display `name` for NPCs and enemies.
   */
  public get logName(): string {
    return this.isPlayer ? PLAYER_LOG_TOKEN : this.name;
  }

  public get currentCarryWeight(): number {
    return this._currentCarryWeight;
  }

  public set currentCarryWeight(weight: number) {
    this._currentCarryWeight = Math.max(0, Number(weight.toFixed(2)));
    this.recalculateStats();
  }

  /**
   * Hard carry limit (1.5x maxCarryWeight). Picking up items beyond this threshold is blocked.
   */
  public get maxOverloadedCarryWeight(): number {
    return Number((this.stats.maxCarryWeight * 1.5).toFixed(2));
  }

  public canCarryAdditionalWeight(additionalWeight: number): boolean {
    return this._currentCarryWeight + additionalWeight <= this.maxOverloadedCarryWeight + 1e-6;
  }

  public getMaxPickupAmount(unitWeight: number, availableAmount: number): number {
    if (availableAmount <= 0) {
      return 0;
    }
    if (unitWeight <= 0) {
      return availableAmount;
    }
    const remainingCapacity = Math.max(0, this.maxOverloadedCarryWeight - this._currentCarryWeight);
    const maxUnits = Math.floor((remainingCapacity + 1e-6) / unitWeight);
    return Math.max(0, Math.min(availableAmount, maxUnits));
  }

  public setBaseAttributes(attrs: Partial<PrimaryAttributes>, refillVitals = false): void {
    this.baseAttributes = {
      ...this.baseAttributes,
      ...attrs,
    };
    this.recalculateStats(refillVitals);
  }

  public recalculateStats(refillVitals = false): void {
    const derived = computeDerivedStats(
      this.baseAttributes,
      this.attributeBonuses,
      this._currentCarryWeight
    );

    const maxHp = this.customStatOverrides.maxHp ?? derived.maxHp;
    const maxMp = this.customStatOverrides.maxMp ?? derived.maxMp;
    const maxSp = this.customStatOverrides.maxSp ?? derived.maxSp;
    const physicalAttack =
      this.customStatOverrides.physicalAttack ??
      this.customStatOverrides.attack ??
      derived.physicalAttack;
    const physicalDefense =
      this.customStatOverrides.physicalDefense ??
      this.customStatOverrides.defense ??
      derived.physicalDefense;

    const currentHp = refillVitals ? maxHp : Math.min(this.stats.hp, maxHp);
    const currentMp = refillVitals ? maxMp : Math.min(this.stats.mp, maxMp);
    const currentSp = refillVitals ? maxSp : Math.min(this.stats.sp, maxSp);

    this.stats = {
      ...derived,
      ...this.customStatOverrides,
      maxHp,
      hp: currentHp,
      maxMp,
      mp: currentMp,
      maxSp,
      sp: currentSp,
      physicalAttack,
      attack: physicalAttack,
      physicalDefense,
      defense: physicalDefense,
      sightRadius: this.stats.sightRadius,
    };
  }

  /**
   * Registers a callback invoked whenever a primary attribute levels up via the "Grow" mechanism.
   */
  public setAttributeLevelUpHandler(handler: (event: AttributeLevelUpEvent) => void): void {
    this.onAttributeLevelUp = handler;
  }

  /**
   * Returns the XP required for `attr` to advance from its current `baseAttributes[attr]` value to +1.
   */
  public getAttributeXpRequired(attr: PrimaryAttributeKey): number {
    return computeAttributeXpRequired(this.baseAttributes[attr], this.growthConfig);
  }

  /**
   * Adds `xpAmount` toward `attr`'s growth progress (when `enableAttributeGrowth` is true and actor is alive).
   * Automatically levels up `baseAttributes[attr]` as many times as thresholds are crossed (carrying over
   * overflow XP), recalculates derived stats while preserving current HP/MP/SP, and notifies any listener.
   */
  public exerciseAttribute(attr: PrimaryAttributeKey, xpAmount: number): AttributeLevelUpEvent[] {
    if (!this.enableAttributeGrowth || xpAmount <= 0 || !this.isAlive()) {
      return [];
    }

    this.attributeXp[attr] = Number((this.attributeXp[attr] + xpAmount).toFixed(4));
    const levelUps: AttributeLevelUpEvent[] = [];

    while (this.attributeXp[attr] + 1e-9 >= this.getAttributeXpRequired(attr)) {
      const required = this.getAttributeXpRequired(attr);
      this.attributeXp[attr] = Math.max(0, Number((this.attributeXp[attr] - required).toFixed(4)));
      const oldValue = this.baseAttributes[attr];
      const newValue = oldValue + 1;
      this.baseAttributes = {
        ...this.baseAttributes,
        [attr]: newValue,
      };
      this.recalculateStats(false);

      const evt: AttributeLevelUpEvent = {
        attribute: attr,
        oldValue,
        newValue,
      };
      levelUps.push(evt);
      this.onAttributeLevelUp?.(evt);
    }

    return levelUps;
  }

  /**
   * Attempts to spend `amount` SP. If sufficient SP is available, deducts it,
   * sets `lastActionSpRegenMultiplier = 0` (0% SP recovery during the action's turn),
   * optionally exercises AGI (`0.6 * amount` XP), and returns `true`.
   */
  public consumeSp(amount: number, exerciseAgi = true): boolean {
    if (this.stats.sp < amount) {
      return false;
    }
    this.stats.sp = Math.max(0, this.stats.sp - amount);
    this.lastActionSpRegenMultiplier = 0;
    if (exerciseAgi && amount > 0) {
      this.exerciseAttribute('agi', amount * ATTRIBUTE_EXERCISE_GAINS.agiXpPerSpSpent);
    }
    return true;
  }

  /**
   * Attempts to spend `amount` MP. If sufficient MP is available, deducts it,
   * exercises WIS (`1.5 * amount` XP), and returns `true`.
   */
  public consumeMp(amount: number, exerciseWis = true): boolean {
    if (this.stats.mp < amount) {
      return false;
    }
    this.stats.mp = Math.max(0, this.stats.mp - amount);
    if (exerciseWis && amount > 0) {
      this.exerciseAttribute('wis', amount * ATTRIBUTE_EXERCISE_GAINS.wisXpPerMpSpent);
    }
    return true;
  }

  /**
   * Executes a magic skill resource spend: consumes `mpCost` MP (exercising WIS) and exercises INT.
   */
  public performMagicSkill(
    mpCost: number,
    intXp: number = ATTRIBUTE_EXERCISE_GAINS.magicCastIntXp
  ): boolean {
    if (!this.consumeMp(mpCost, true)) {
      return false;
    }
    if (intXp > 0) {
      this.exerciseAttribute('int', intXp);
    }
    return true;
  }

  public get sightRadius(): number {
    return this.stats.sightRadius;
  }

  public set sightRadius(radius: number) {
    this.stats.sightRadius = Math.max(1, radius);
  }

  public get speed(): number {
    return this.stats.speed;
  }

  public isAlive(): boolean {
    return this.stats.hp > 0;
  }

  /**
   * Advances this actor's scheduled timestamp on the dungeon timeline based on action cost and speed.
   * An actor with speed 100 pays baseTimeCost ticks; faster actors (higher AGI -> speed > 100) pay fewer ticks.
   */
  public advanceTime(baseTimeCost: number): number {
    const effectiveCost = Math.max(
      1,
      Math.round((baseTimeCost * 100) / Math.max(1, this.stats.speed))
    );
    this.nextActionTime += effectiveCost;
    return effectiveCost;
  }

  /**
   * Regenerates HP (from CON), MP (from WIS), and SP (from CON scaled by `lastActionSpRegenMultiplier`:
   * 100% when resting, 50% when moving/non-SP action, 0% when consuming SP) proportionally to elapsed dungeon timeline ticks.
   */
  public regenerateOverTicks(elapsedTicks: number): {
    hpRestored: number;
    mpRestored: number;
    spRestored: number;
  } {
    if (elapsedTicks <= 0 || !this.isAlive()) {
      return { hpRestored: 0, mpRestored: 0, spRestored: 0 };
    }

    let hpRestored = 0;
    let mpRestored = 0;
    let spRestored = 0;

    if (this.stats.hp < this.stats.maxHp) {
      this.hpRegenAccumulator += (elapsedTicks / 100) * this.stats.hpRegenPer100Ticks;
      const wholeHp = Math.floor(this.hpRegenAccumulator);
      if (wholeHp >= 1) {
        this.hpRegenAccumulator -= wholeHp;
        const prevHp = this.stats.hp;
        this.stats.hp = Math.min(this.stats.maxHp, this.stats.hp + wholeHp);
        hpRestored = this.stats.hp - prevHp;
      }
    } else {
      this.hpRegenAccumulator = 0;
    }

    if (this.stats.mp < this.stats.maxMp) {
      this.mpRegenAccumulator += (elapsedTicks / 100) * this.stats.mpRegenPer100Ticks;
      const wholeMp = Math.floor(this.mpRegenAccumulator);
      if (wholeMp >= 1) {
        this.mpRegenAccumulator -= wholeMp;
        const prevMp = this.stats.mp;
        this.stats.mp = Math.min(this.stats.maxMp, this.stats.mp + wholeMp);
        mpRestored = this.stats.mp - prevMp;
      }
    } else {
      this.mpRegenAccumulator = 0;
    }

    if (this.stats.sp < this.stats.maxSp) {
      if (this.lastActionSpRegenMultiplier > 0) {
        this.spRegenAccumulator +=
          (elapsedTicks / 100) *
          this.stats.spRegenPer100Ticks *
          this.lastActionSpRegenMultiplier;
        const wholeSp = Math.floor(this.spRegenAccumulator);
        if (wholeSp >= 1) {
          this.spRegenAccumulator -= wholeSp;
          const prevSp = this.stats.sp;
          this.stats.sp = Math.min(this.stats.maxSp, this.stats.sp + wholeSp);
          spRestored = this.stats.sp - prevSp;
        }
      }
    } else {
      this.spRegenAccumulator = 0;
    }

    return { hpRestored, mpRestored, spRestored };
  }

  public toActorSaveState(): SerializedActorState {
    const hasOverrides = Object.keys(this.customStatOverrides).length > 0;
    return {
      id: this.id,
      name: this.name,
      spriteKey: this.spriteKey,
      position: { x: this.position.x, y: this.position.y },
      baseAttributes: { ...this.baseAttributes },
      attributeBonuses: { ...this.attributeBonuses },
      attributeXp: { ...this.attributeXp },
      growthConfig: { ...this.growthConfig },
      enableAttributeGrowth: this.enableAttributeGrowth,
      hp: this.stats.hp,
      mp: this.stats.mp,
      sp: this.stats.sp,
      sightRadius: this.stats.sightRadius,
      nextActionTime: this.nextActionTime,
      lastActionSpRegenMultiplier: this.lastActionSpRegenMultiplier,
      hpRegenAccumulator: this.hpRegenAccumulator,
      mpRegenAccumulator: this.mpRegenAccumulator,
      spRegenAccumulator: this.spRegenAccumulator,
      ...(hasOverrides ? { customStatOverrides: { ...this.customStatOverrides } } : {}),
      inventory: this.inventory.getItems().map((item) => item.toSaveData()),
    };
  }

  public restoreActorSaveState(saved: Partial<SerializedActorState>): void {
    if (saved.position) {
      this.position = { x: saved.position.x, y: saved.position.y };
    }
    if (saved.baseAttributes) {
      this.baseAttributes = {
        ...DEFAULT_PRIMARY_ATTRIBUTES,
        ...saved.baseAttributes,
      };
    }
    if (saved.attributeBonuses) {
      this.attributeBonuses = { ...saved.attributeBonuses };
    }
    if (saved.attributeXp) {
      this.attributeXp.str = saved.attributeXp.str ?? 0;
      this.attributeXp.con = saved.attributeXp.con ?? 0;
      this.attributeXp.int = saved.attributeXp.int ?? 0;
      this.attributeXp.wis = saved.attributeXp.wis ?? 0;
      this.attributeXp.agi = saved.attributeXp.agi ?? 0;
      this.attributeXp.luk = saved.attributeXp.luk ?? 0;
    }
    if (saved.growthConfig) {
      this.growthConfig = {
        ...DEFAULT_ATTRIBUTE_GROWTH_CONFIG,
        ...saved.growthConfig,
      };
    }
    if (typeof saved.enableAttributeGrowth === 'boolean') {
      this.enableAttributeGrowth = saved.enableAttributeGrowth;
    }

    this.inventory.clear();
    if (Array.isArray(saved.inventory)) {
      for (const itemData of saved.inventory) {
        this.inventory.addItem(deserializeItem(itemData));
      }
    }

    this.recalculateStats(true);

    if (typeof saved.sightRadius === 'number') {
      this.stats.sightRadius = Math.max(1, saved.sightRadius);
    }
    if (typeof saved.hp === 'number') {
      this.stats.hp = Math.max(0, Math.min(this.stats.maxHp, saved.hp));
    }
    if (typeof saved.mp === 'number') {
      this.stats.mp = Math.max(0, Math.min(this.stats.maxMp, saved.mp));
    }
    if (typeof saved.sp === 'number') {
      this.stats.sp = Math.max(0, Math.min(this.stats.maxSp, saved.sp));
    }
    if (typeof saved.nextActionTime === 'number') {
      this.nextActionTime = Math.max(0, saved.nextActionTime);
    }
    if (
      saved.lastActionSpRegenMultiplier === 0 ||
      saved.lastActionSpRegenMultiplier === 0.5 ||
      saved.lastActionSpRegenMultiplier === 1
    ) {
      this.lastActionSpRegenMultiplier = saved.lastActionSpRegenMultiplier;
    }
    this.hpRegenAccumulator = saved.hpRegenAccumulator ?? 0;
    this.mpRegenAccumulator = saved.mpRegenAccumulator ?? 0;
    this.spRegenAccumulator = saved.spRegenAccumulator ?? 0;
  }
}
