import { Tile } from './Tile';
import { ALL_DIRECTIONS, DoorState, Point, TileType } from './types';

export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export function rectCenter(rect: Rect): Point {
  return {
    x: Math.floor(rect.x + rect.width / 2),
    y: Math.floor(rect.y + rect.height / 2),
  };
}

export function rectsOverlap(a: Rect, b: Rect, padding = 1): boolean {
  return (
    a.x - padding < b.x + b.width &&
    a.x + a.width + padding > b.x &&
    a.y - padding < b.y + b.height &&
    a.y + a.height + padding > b.y
  );
}

export const DEFAULT_ENEMY_DENSITY = 12;
export const DEFAULT_ENEMY_SPAWN_PROBABILITY = 0.15;

export interface DungeonMapOptions {
  readonly enemyDensity?: number;
  readonly enemySpawnProbability?: number;
}

/**
 * 2D grid map of Tiles with bounds checking, adjacency queries, enemy spawning density/probability,
 * and ASCII serialization.
 */
export class DungeonMap {
  public readonly width: number;
  public readonly height: number;
  public enemyDensity: number;
  public enemySpawnProbability: number;
  private readonly grid: Tile[][];

  constructor(
    width: number,
    height: number,
    defaultTileFactory: () => Tile = () => Tile.createWall(),
    options?: DungeonMapOptions
  ) {
    if (width <= 0 || height <= 0) {
      throw new Error(`Invalid DungeonMap dimensions: ${width}x${height}`);
    }
    this.width = width;
    this.height = height;
    this.enemyDensity = Math.max(0, options?.enemyDensity ?? DEFAULT_ENEMY_DENSITY);
    this.enemySpawnProbability = Math.min(
      1,
      Math.max(0, options?.enemySpawnProbability ?? DEFAULT_ENEMY_SPAWN_PROBABILITY)
    );
    this.grid = Array.from({ length: height }, () =>
      Array.from({ length: width }, () => defaultTileFactory())
    );
  }

  public inBounds(x: number, y: number): boolean {
    return x >= 0 && x < this.width && y >= 0 && y < this.height;
  }

  public getTile(x: number, y: number): Tile | null {
    if (!this.inBounds(x, y)) {
      return null;
    }
    return this.grid[y][x];
  }

  public setTile(x: number, y: number, tile: Tile): void {
    if (!this.inBounds(x, y)) {
      return;
    }
    this.grid[y][x] = tile;
  }

  public isPassable(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    return tile !== null && tile.isPassable();
  }

  /**
   * Returns all walkable (passable FLOOR or OPEN door) coordinates on the map.
   */
  public getWalkablePoints(): Point[] {
    const points: Point[] = [];
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (this.isPassable(x, y)) {
          points.push({ x, y });
        }
      }
    }
    return points;
  }

  public isTransparent(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    return tile !== null && tile.isTransparent();
  }

  /**
   * Returns true if the tile is Either FLOOR or DOOR (open or closed).
   * Useful for verifying map connectivity across closed doors.
   */
  public isTraversableIgnoreClosedDoors(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    if (!tile) return false;
    return tile.type === TileType.FLOOR || tile.type === TileType.DOOR;
  }

  public getAdjacentPoints(origin: Point, includeDiagonals = true): Point[] {
    const points: Point[] = [];
    for (const dir of ALL_DIRECTIONS) {
      if (!includeDiagonals && dir.dx !== 0 && dir.dy !== 0) {
        continue;
      }
      const nx = origin.x + dir.dx;
      const ny = origin.y + dir.dy;
      if (this.inBounds(nx, ny)) {
        points.push({ x: nx, y: ny });
      }
    }
    return points;
  }

  public carveRect(rect: Rect): void {
    for (let y = rect.y; y < rect.y + rect.height; y++) {
      for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (this.inBounds(x, y)) {
          this.setTile(x, y, Tile.createFloor());
        }
      }
    }
  }

  /**
   * Parses an ASCII map representation for deterministic testing.
   * Legend:
   *   '#' = Wall
   *   '.' = Floor
   *   '+' = Closed Door
   *   '/' = Open Door
   *   '@' = Player spawn on a Floor tile
   */
  public static fromAscii(
    lines: readonly string[],
    options?: DungeonMapOptions
  ): { map: DungeonMap; playerSpawn: Point } {
    if (lines.length === 0 || lines[0].length === 0) {
      throw new Error('ASCII map must have at least 1 non-empty line');
    }
    const height = lines.length;
    const width = Math.max(...lines.map((l) => l.length));
    const map = new DungeonMap(width, height, () => Tile.createWall(), {
      enemyDensity: options?.enemyDensity ?? DEFAULT_ENEMY_DENSITY,
      enemySpawnProbability: options?.enemySpawnProbability ?? 0,
    });
    let playerSpawn: Point = { x: 0, y: 0 };

    for (let y = 0; y < height; y++) {
      const row = lines[y];
      for (let x = 0; x < width; x++) {
        const ch = row[x] ?? '#';
        switch (ch) {
          case '.':
            map.setTile(x, y, Tile.createFloor());
            break;
          case '@':
            map.setTile(x, y, Tile.createFloor());
            playerSpawn = { x, y };
            break;
          case '+':
            map.setTile(x, y, Tile.createDoor(DoorState.CLOSED));
            break;
          case '/':
            map.setTile(x, y, Tile.createDoor(DoorState.OPEN));
            break;
          case '#':
          default:
            map.setTile(x, y, Tile.createWall());
            break;
        }
      }
    }

    return { map, playerSpawn };
  }

  public toAscii(playerPos?: Point): string {
    const rows: string[] = [];
    for (let y = 0; y < this.height; y++) {
      let line = '';
      for (let x = 0; x < this.width; x++) {
        if (playerPos && playerPos.x === x && playerPos.y === y) {
          line += '@';
          continue;
        }
        const tile = this.getTile(x, y)!;
        if (tile.type === TileType.WALL) {
          line += '#';
        } else if (tile.type === TileType.FLOOR) {
          line += '.';
        } else if (tile.type === TileType.DOOR) {
          line += tile.doorState === DoorState.OPEN ? '/' : '+';
        }
      }
      rows.push(line);
    }
    return rows.join('\n');
  }
}
