import { formatLogMessage, LanguageCode, LogMessageKey } from '../i18n/translations';
import { MAX_LOG_HISTORY } from './types';

export { MAX_LOG_HISTORY };

export type GameEventType = 'info' | 'move' | 'door' | 'combat' | 'turn';

export interface GameEvent {
  readonly type: GameEventType;
  readonly message: string;
  readonly timestamp: number;
  readonly messageKey?: LogMessageKey;
  readonly params?: Readonly<Record<string, string | number>>;
}

export type GameEventListener = (event: GameEvent) => void;

/**
 * Lightweight Pub/Sub event bus for decoupling core game actions from UI status/message logs.
 * Retains only the latest `maxHistory` (default `500`) events in a rolling buffer.
 */
export class GameEventBus {
  private readonly listeners = new Set<GameEventListener>();
  private readonly history: GameEvent[] = [];
  private readonly maxHistory: number;
  private emittedSequence = 0;

  constructor(maxHistory = MAX_LOG_HISTORY) {
    this.maxHistory = Math.max(1, maxHistory);
  }

  public get maxHistorySize(): number {
    return this.maxHistory;
  }

  /**
   * Monotonically increasing count of emitted events in this session (continues incrementing
   * even after `history` reaches `maxHistory` and trims older entries).
   */
  public get totalEmittedCount(): number {
    return this.emittedSequence;
  }

  public emit(event: GameEvent): void {
    this.emittedSequence += 1;
    this.history.push(event);
    if (this.history.length > this.maxHistory) {
      this.history.splice(0, this.history.length - this.maxHistory);
    }
    for (const listener of this.listeners) {
      listener(event);
    }
  }

  public log(
    message: string,
    type: GameEventType = 'info',
    timestamp = 0,
    messageKey?: LogMessageKey,
    params?: Readonly<Record<string, string | number>>
  ): void {
    this.emit({ type, message, timestamp, messageKey, params });
  }

  public subscribe(listener: GameEventListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  public getRecentEvents(count = 10): readonly GameEvent[] {
    return this.history.slice(-count);
  }

  public getAllEvents(): readonly GameEvent[] {
    return [...this.history];
  }

  public clear(): void {
    this.history.length = 0;
  }

  public restoreEvents(events: readonly GameEvent[]): void {
    this.history.length = 0;
    for (const ev of events.slice(-this.maxHistory)) {
      this.history.push({
        type: ev.type,
        message: ev.message,
        timestamp: ev.timestamp,
        messageKey: ev.messageKey,
        params: ev.params ? { ...ev.params } : undefined,
      });
    }
    this.emittedSequence = this.history.length;
  }
}

/**
 * Resolves the display string for a GameEvent in the requested language.
 */
export function resolveEventMessage(event: GameEvent, lang: LanguageCode): string {
  if (event.messageKey) {
    return formatLogMessage(lang, event.messageKey, event.params);
  }
  return event.message;
}
